SELECT percentile_cont(0.25) within GROUP (ORDER BY value) AS q25, percentile_cont(0.50) within GROUP (ORDER BY value) AS q50, percentile_cont(0.75) within GROUP (ORDER BY value) AS q75, MIN(value) AS min_value, MAX(value) AS max_value FROM labevents JOIN patients ON labevents.subject_id = patients.subject_id WHERE patients.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, patients.dob)) BETWEEN 59 AND 69 AND labevents.itemid = 757071 AND labevents.value > 0.014;